const $=id=>document.getElementById(id);let endpoint='',history=[],busy=false;
function configure(value){try{const url=new URL(value);if(url.protocol!=='https:'||!url.hostname.endsWith('.workers.dev'))throw Error();endpoint=url.href.replace(/\/$/,'');$('bridge').value=endpoint;sessionStorage.setItem('taiwan-cli-endpoint',endpoint);$('settings').open=false;$('status').textContent='接続先を設定しました。';return true}catch{$('status').textContent='専用のWorkers接続URLを確認してください。';return false}}
const initial=new URLSearchParams(location.hash.slice(1)).get('bridge');if(initial){configure(initial);window.history.replaceState(null,'',location.pathname);}else{try{const saved=sessionStorage.getItem('taiwan-cli-endpoint');if(saved)configure(saved)}catch{}}
$('connect').onclick=()=>configure($('bridge').value.trim());
function bubble(role,text){const div=document.createElement('div');div.className='message '+role;const label=document.createElement('small'),body=document.createElement('span');label.textContent=role==='user'?'あなた':'台湾相談';body.textContent=text;div.append(label,body);$('messages').append(div);div.scrollIntoView({block:'nearest'});}
function setBusy(value){busy=value;$('send').disabled=value;$('clear').disabled=value;$('question').disabled=value;}
async function api(path,options={}){const r=await fetch(endpoint+path,{...options,referrerPolicy:'no-referrer',signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok||data.error)throw Error(data.error||'接続できませんでした。');return data;}
$('clear').onclick=()=>{history=[];$('messages').replaceChildren();$('status').textContent='新しい会話を開始しました。';};
$('chat-form').onsubmit=async event=>{event.preventDefault();if(busy)return;if(!endpoint){$('settings').open=true;$('status').textContent='接続先の設定が必要です。';return}const text=$('question').value.trim();if(!text)return;const input=[...history.slice(-6),{role:'user',content:text}];setBusy(true);bubble('user',text);$('question').value='';$('status').textContent='GitHubに実行を依頼しています…';try{const {id}=await api('/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:input})});for(let attempt=0;attempt<100;attempt++){await new Promise(resolve=>setTimeout(resolve,4000));const result=await api('/jobs/'+id);if(result.status==='completed'){if(typeof result.answer!=='string')throw Error('回答の形式が不正です。');bubble('assistant',result.answer);history=[...input,{role:'assistant',content:result.answer.slice(0,1500)}];$('status').textContent='回答しました。';return}if(result.status==='failed')throw Error(result.error||'実行に失敗しました。');$('status').textContent=result.status==='in_progress'?'Luna mediumが回答を作成しています…':'GitHubの起動を待っています…';}throw Error('実行待ちが長くなっています。GitHubの実行履歴を確認してください。');}catch(error){$('status').textContent=error.message;$('question').value=text;}finally{setBusy(false);$('question').focus();}};
